      [2,"følsomme personoplysninger","sensitive personal data","чувствительные персональные данные","чутливі персональні дані","dane wrażliwe","date personale sensibile","jautrūs asmens duomenys (specialių kategorijų)","чувствителни лични данни (специални категории)"],
      [2,"fortrolig","confidential","конфиденциальный","конфіденційний","poufny","confidențial","konfidencialus","поверителен"],
      [2,"et sikkerhedsbrud","security breach","нарушение безопасности данных","порушення безпеки даних","naruszenie bezpieczeństwa danych","încălcare a securității datelor","saugumo pažeidimas","нарушение на сигурността"],
      [3,"at kryptere","to encrypt","зашифровать","зашифрувати","zaszyfrować","a cripta","šifruoti","криптирам"],
      [1,"at låse skærmen","to lock the screen","заблокировать экран","заблокувати екран","zablokować ekran","a bloca ecranul","užrakinti ekraną","заключвам екрана"],
      [3,"en passwordmanager","password manager","менеджер паролей","менеджер паролів","menedżer haseł","manager de parole","slaptažodžių tvarkyklė","мениджър на пароли"],
      [3,"databeskyttelsesforordningen (GDPR)","General Data Protection Regulation (GDPR)","Общий регламент по защите данных (GDPR)","Загальний регламент про захист даних (GDPR)","RODO","Regulamentul general privind protecția datelor (GDPR)","Bendrasis duomenų apsaugos reglamentas (BDAR, GDPR)","Общ регламент относно защитата на данните (ОРЗД, GDPR)"],
      [3,"Datatilsynet","Danish Data Protection Agency","Датское агентство по защите данных","Данське агентство із захисту даних","duński organ ochrony danych osobowych","Autoritatea daneză pentru protecția datelor","Danijos duomenų apsaugos institucija (Datatilsynet)","Агенция за защита на данните в Дания (Datatilsynet)"],
      [1,"en phishingmail","phishing email","фишинговое письмо","фішинговий лист","e-mail phishingowy","e-mail de phishing","sukčiavimo (fišingo) el. laiškas","фишинг имейл"],
      [3,"en hacker","hacker","хакер","хакер","haker","hacker","programišius (hakeris)","хакер"]
